const beforeCddRich=richVar;
richVar=function(p){const v=beforeCddRich(p);return{precDecision:'À vérifier',precPriorGross:'',precRate:'10',precRateReference:'',precReason:'',precExcludedCurrent:'0',...v,precContract:p.contract,precScheme:personDefaults(p).scheme,precEndDate:v.precEndDate||p.actualEndDate||p.endDate||'',precPeriod:period()};};
const beforeCddMarkup=variableMarkup;
variableMarkup=function(p){const v=richVar(p);return beforeCddMarkup(p)+section('Fin de CDD · prime de précarité',selectField('precDecision','Traitement de la prime de précarité',v.precDecision,['À vérifier','Calculer','Non due'])+field('precEndDate','Date de fin du CDD retenue',v.precEndDate,'date')+field('precPriorGross','Brut éligible des mois précédents de ce CDD (€)',v.precPriorGross,'number','min="0" step=".01"')+num('precExcludedCurrent','Éléments du brut du mois exclus de cette assiette (€)',v.precExcludedCurrent)+field('precRate','Taux de prime de précarité (%)',v.precRate,'number','min="6" max="100" step=".0001"')+field('precRateReference','Accord / clause et contreparties justifiant un autre taux',v.precRateReference)+field('precReason','Motif documenté si indemnité non due',v.precReason)+`<input type="hidden" name="precContract" value="${esc(p.contract)}"><input type="hidden" name="precScheme" value="${esc(personDefaults(p).scheme)}"><input type="hidden" name="precPeriod" value="${esc(period())}"><p id="precLive" class="wide notice" aria-live="polite"></p><p class="wide muted">Cas général : 10 % du brut éligible de tout le contrat et de ses renouvellements, incluant le mois de sortie, hors prime elle-même, remboursements de frais et indemnité compensatrice de congés payés de fin de contrat. Les indemnités de congés payés pris pendant le contrat ne sont pas exclues systématiquement. Le cumul antérieur est à rapprocher des bulletins ; il n’est pas déduit des seuls brouillons de test.</p><p class="wide muted">Non-versement à justifier : poursuite en CDI, refus d’un CDI pour emploi identique/similaire et rémunération au moins équivalente, rupture à l’initiative du salarié, faute grave, force majeure, CDD saisonnier/d’usage, certains contrats aidés ou de formation, vacances scolaires/universitaires. Apprentissage : pas d’application automatique. Une rupture d’un commun accord ne supprime pas automatiquement la prime. Le mode CIBTP n’exonère pas la prime de précarité.</p><p class="wide muted">Bâtiment : références vérifiées IDCC 1596, 1597 et 2609 ; cadres 2420 et autres conventions / accords : applicabilité à contrôler. Taux réduit à 6 % uniquement avec accord applicable et contreparties de formation, jamais par défaut. <a href="https://code.travail.gouv.fr/contribution/1596-dans-le-cadre-dun-cdd-quel-est-le-montant-de-lindemnite-de-fin-de-contrat" target="_blank" rel="noopener">Référence ouvriers Bâtiment</a> · <a href="https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000006901219" target="_blank" rel="noopener">Code du travail L1243-8</a></p>`);};
const beforeCddEngine=engineInput;
engineInput=function(v){const input=beforeCddEngine(v);if(v.precDecision==='Non due'&&!String(v.precReason||'').trim())throw Error('Renseignez le motif de non-versement de la prime de précarité.');if(v.precDecision!=='Calculer')return{...input,precarity:'0'};const without=PayrollTest.calculate({...input,precarity:'0',rows:[],advance:'0',otherDeduction:'0',taxableNet:'0',socialNet:'',pasRate:'0'});const result=CddIndemnity.calculate(v,without.gross,v.precPeriod||period());return{...input,precarity:result.amount.toFixed(2),precarityBase:result.base};};
const beforeCddRefresh=refreshCalculations;
refreshCalculations=function(){beforeCddRefresh();const out=$('#precLive');if(!out)return;try{const v=Object.fromEntries(new FormData($('#form')));const input=engineInput(autoVariables(v));out.textContent=v.precDecision==='Calculer'?`Assiette du contrat : ${euroFmt(input.precarityBase)} × ${v.precRate} % = ${euroFmt(input.precarity)} bruts. Ajouté au brut et aux assiettes de cotisations.`:v.precDecision==='Non due'?'Aucun montant ajouté. Motif : '+v.precReason:'Situation à vérifier : aucun montant ajouté.';}catch(e){out.textContent=e.message;}};
const beforeCddRead=readVariableForm;
readVariableForm=function(f){const v=beforeCddRead(f);engineInput(v);return v;};
const beforeCddDraft=draftMarkup;
draftMarkup=function(d){return beforeCddDraft(d).replace('<tr><td>TOTAL BRUT TEST',`${d.result.precarity?`<tr><td>Indemnité de fin de CDD — précarité</td><td>${esc(d.variables.precRate)} % du brut éligible du contrat</td><td></td><td>${euroFmt(d.result.precarity)}</td><td></td></tr>`:''}<tr><td>TOTAL BRUT TEST`);};
const beforeCddIssues=issues;
issues=function(p,v){const list=beforeCddIssues(p,v);if(p.contract==='CDD'&&v.precDecision==='À vérifier')list.push('Indemnité de fin de CDD : droit, assiette et taux à vérifier');if(v.precDecision==='Calculer')list.push('Précarité calculée sur cumul fourni : contrôler l’assiette et son inclusion dans une éventuelle indemnité compensatrice de congés payés');return list;};
